	}

	var envelope apiErrorEnvelope
	if err := json.Unmarshal(payload, &envelope); err != nil {
		return err
	}

	apiErr.Code = envelope.Error.Code
	apiErr.Message = envelope.Error.Message
	apiErr.Reasons = []string{}

