// Do sends req through the generated service, or the default client when the
// service is absent.
func (c pagesClient) Do(req *http.Request) (*http.Response, error) {
	if c.service == nil {
		return http.DefaultClient.Do(req)
	}

	clone := *req
	clone.Header = req.Header.Clone()
	clone.URL = cloneURL(req.URL)

	return c.service.HttpClient.Do(&clone)
}

